    // (2x(1-x))^m * sum_{j=0}^{n-m} C(n-m, j) * (-1)^j * (2x(1-x))^j
    // = sum_{j=0}^{n-m} C(n-m, j) * (-1)^j * 2^{m+j} * x^{m+j} * (1-x)^{m+j}

    // So I(m) = sum_{j=0}^{n-m} C(n-m, j) * (-1)^j * 2^{m+j} * integral_0^1 x^{m+j} (1-x)^{m+j} dx
    // = sum_{j=0}^{n-m} C(n-m, j) * (-1)^j * 2^{m+j} * (m+j)! * (m+j)! / (2(m+j)+1)!

    // This is still complex, but we can compute it

    // Let's compute the answer using this formula

    let ans = 0n;
    for (let m = k; m <= n; m++) {
        let Im = 0n;
        for (let j = 0; j <= n - m; j++) {
            const c = comb(n - m, j);
            const sign = (j % 2 === 0) ? 1n : -1n;
            const pow2 = modPow(2, m + j);
            const a = m + j;
            const b = m + j;
            // integral_0^1 x^a (1-x)^b dx = a!b!/(a+b+1)!
            const integral = fact[a] * fact[b] % BigInt(MOD) * modInv(Number(fact[a + b + 1])) % BigInt(MOD);
            Im = (Im + sign * c * BigInt(pow2) % BigInt(MOD) * integral) % BigInt(MOD);
        }
        const cnm = comb(n, m);
        ans = (ans + cnm * Im) % BigInt(MOD);
    }

    ans = ans * BigInt(l) % BigInt(MOD);
    ans = (ans + BigInt(MOD)) % BigInt(MOD);
    console.log(Number(ans));
}

